### solution

#### dynamic programming with memoization

```cpp
#include <vector>
#include <unordered_map>
#include <string>

int maxIncreasingSubseq(std::vector<int> numbers, int i, int lastNum, std::unordered_map<std::string, int> &memo) {
  std::string key = std::to_string(i) + "," + std::to_string(lastNum);

  if (memo.count(key) > 0) {
    return memo[key];
  }

  if (i == numbers.size()) {
    return 0;
  }

  int dontTake = maxIncreasingSubseq(numbers, i + 1, lastNum, memo);

  int take = -1;
  if (numbers[i] > lastNum) {
    take = 1 + maxIncreasingSubseq(numbers, i + 1, numbers[i], memo);
  }

  if (take > dontTake) {
    memo[key] = take;
    return take;
  } else {
    memo[key] = dontTake;
    return dontTake;
  }
}

int maxIncreasingSubseq(std::vector<int> numbers) {
  std::unordered_map<std::string, int> memo;
  return maxIncreasingSubseq(numbers, 0, -1, memo);
}
```

- n = length of array
- Time: O(n^2)
- Space: O(n^2)
